//! `ConnexIntByInt` (`BRepOffset_Inter3d.cxx:446-1041`): the intersections of
//! the offset faces of initial faces that meet through an edge (stage 1) or
//! through a lone vertex (stage 2, planar mode only), plus the post-treatment
//! that splits each shared intersection edge into one instance per localized
//! part.
//!
//! Control flow, in the reference's order:
//!
//! 1. `VEmap` receives the edges of `SI` (`cxx:467`); in planar mode also the
//!    edges generated by those edges (`:472-478`), then the vertices of `SI`
//!    and of `Analyse.NewFaces()` (`:481-487`).
//! 2. Planar mode only (`:496-649`): the internal edges of every face are
//!    collected in `aDMFEI` (`:505-521`), then every vertex is inspected
//!    (`:525-648`): `aLF` is the set of faces reached through the vertex via
//!    its edges, and the pairs whose common edges are neither internal nor
//!    shared by exactly two faces go to `aDMVLF1` / `aDMVLF2`.
//! 3. Main loop (`:654-850`): an edge of `Convex` / `Concave` concavity takes
//!    the sorted side and its two ancestors; a vertex entry takes the pairs of
//!    `aDMVLF1/2` and `mySide`. The offset faces `MapSF(F).Face()` are
//!    enlarged once each (`CheckBounds` + `EnLargeFace`, cached in `MES`), then
//!    `Inter3D` runs on the pair unless `IsDone`.
//!    - not done and a non-empty `LInt1`: `Store`, the intersection edges are
//!      added to the compound bound to `aS` in `Build`, indexed in `aDMIntE`
//!      (edge -> `aS`) and `aDMIntFF` (edge -> its two faces);
//!    - not done and empty `LInt1`: `aS` goes to `Failed`;
//!    - already done (`:801-849`, OCC4455): the compound is rebuilt from the
//!      edges `NF1` already generated that `NF2` also generated.
//! 4. Post-treatment (`:852-1041`): for every intersection edge shared by two
//!    or more localized parts, the parts are grouped into connexity blocks
//!    (`BOPTools_AlgoTools::MakeConnexityBlocks` on the edges, plus the
//!    connection edges of `aF1` / `aF2` that touch two parts, plus the lone
//!    vertices as their own blocks); every block but the first gets a fresh
//!    `MakeSplitEdge` instance, linked to `MES(MapSF(aF1).Face())` and
//!    `MES(MapSF(aF2).Face())` and substituted for the shared edge in each
//!    part's compound.
//!
//! Port guards, each replacing an OCCT exception or a null-handle dereference,
//! never a branch:
//!
//! * `MapSF(F1)` / `MapSF(F2)` raising `Standard_NoSuchObject` (`cxx:726-727`)
//!   and an offset face that was never built (`Face()` null) skip the pair.
//! * `EnLargeFace` leaving `NF` null because `BRep_Tool::Surface` is null
//!   (`EnLargeFace` dereferences it at `BRepOffset_Tool.cxx:3461`) skips the
//!   pair without binding `MES`.
//! * `Build.ChangeFind(aS)` on an unbound key (`cxx:1024`) skips that part.
//! * a `MakeSplitEdge` failure (`cxx:1008`) skips that block.
//!
//! `TopoDS_Shape` list membership uses `IsSame`, so `aDMIntE` / `aDMIntFF` keep
//! the reference's `TopTools_ShapeMapHasher` identity and insertion order.

use std::collections::{HashMap, HashSet};

use crate::abs::{ShapeType, State};
use crate::algo_tools::AlgoTools;
use crate::brep_offset::{
    make_connexity_blocks, Analyse, BRepOffsetTool, EnLargeFaceOptions, ShapeMap,
};
use crate::brep_tool::BRepTool;
use crate::builder::TopoBuilder;
use crate::chfi_ds::TypeOfConcavity;
use crate::shape::{Edge, Face, TopoShape};
use crate::topo_tools::{edge_vertices, explorer_shapes, is_same, shape_map_key, ShapeMapKey};

use super::{BRepOffsetInter3d, MapSf, ShapeIndexedMap};

/// `NCollection_IndexedDataMap<TopoDS_Shape, NCollection_List<TopoDS_Shape>>`:
/// insertion ordered, `IsSame`-unique keys, add-or-get answers the existing
/// entry (`NCollection_IndexedDataMap.hxx:503-506`).
struct IndexedListMap {
    entries: Vec<(TopoShape, Vec<TopoShape>)>,
    index: HashMap<ShapeMapKey, usize>,
}

impl IndexedListMap {
    fn new() -> Self {
        Self {
            entries: Vec::new(),
            index: HashMap::new(),
        }
    }

    /// `Add(theKey, theItem)` followed by `operator()(theKey)`: appends an
    /// empty list for a new key and answers the bound list either way.
    fn add_or_get(&mut self, key: &TopoShape) -> &mut Vec<TopoShape> {
        let k = shape_map_key(key);
        let i = match self.index.get(&k) {
            Some(i) => *i,
            None => {
                self.entries.push((key.clone(), Vec::new()));
                self.index.insert(k, self.entries.len() - 1);
                self.entries.len() - 1
            }
        };
        &mut self.entries[i].1
    }

    /// `ChangeSeek(theKey)`: `None` is the null pointer of an unbound key.
    fn seek_mut(&mut self, key: &TopoShape) -> Option<&mut Vec<TopoShape>> {
        let i = *self.index.get(&shape_map_key(key))?;
        Some(&mut self.entries[i].1)
    }

    fn extent(&self) -> usize {
        self.entries.len()
    }

    /// `FindKey(i)` with the list bound to it, 0-based.
    fn value(&self, i: usize) -> Option<&(TopoShape, Vec<TopoShape>)> {
        self.entries.get(i)
    }
}

impl BRepOffsetInter3d {
    /// `ConnexIntByInt(SI, MapSF, Analyse, MES, Build, Failed, theRange,
    /// bIsPlanar)` (`cxx:446-1041`).
    pub fn connex_int_by_int(
        &mut self,
        si: &TopoShape,
        map_sf: &MapSf,
        analyse: &Analyse,
        mes: &mut ShapeMap,
        build: &mut ShapeMap,
        failed: &mut Vec<TopoShape>,
        is_planar: bool,
    ) {
        let builder = TopoBuilder::new();

        // `TopExp::MapShapes(SI, TopAbs_EDGE, VEmap)` (`cxx:467`).
        let mut vemap = ShapeIndexedMap::new();
        for s in explorer_shapes(si, ShapeType::Edge) {
            vemap.add(&s);
        }
        let mut a_nb = vemap.extent();

        // `aDMVLF1` / `aDMVLF2` (`cxx:490-491`): the face pairs connected
        // through a lone vertex.
        let mut dmvlf1: HashMap<ShapeMapKey, Vec<TopoShape>> = HashMap::new();
        let mut dmvlf2: HashMap<ShapeMapKey, Vec<TopoShape>> = HashMap::new();

        if is_planar {
            // `cxx:469-478`: the edges generated by the edges of `SI`.
            for i in 1..=a_nb {
                let Some(shape) = vemap.value(i).cloned() else {
                    continue;
                };
                let a_e = Edge(shape);
                if let Some(a_f_gen) = analyse.generated(&a_e.0) {
                    for s in explorer_shapes(&a_f_gen, ShapeType::Edge) {
                        vemap.add(&s);
                    }
                }
            }

            // `cxx:481-487`: the vertices of `SI` and of the new faces.
            for s in explorer_shapes(si, ShapeType::Vertex) {
                vemap.add(&s);
            }
            for nf in analyse.new_faces() {
                for s in explorer_shapes(nf, ShapeType::Vertex) {
                    vemap.add(&s);
                }
            }

            // `cxx:503-521`: `aDMFEI`, the internal edges of every face.
            let mut dmfei: HashMap<ShapeMapKey, HashSet<ShapeMapKey>> = HashMap::new();
            for f_shape in explorer_shapes(si, ShapeType::Face) {
                let mut mei: HashSet<ShapeMapKey> = HashSet::new();
                for e_shape in explorer_shapes(&f_shape, ShapeType::Edge) {
                    let o = e_shape.orientation();
                    if o != crate::abs::Orientation::Forward
                        && o != crate::abs::Orientation::Reversed
                    {
                        mei.insert(shape_map_key(&e_shape));
                    }
                }
                if !mei.is_empty() {
                    dmfei.insert(shape_map_key(&f_shape), mei);
                }
            }

            // `cxx:525-648`: the face pairs connected through each vertex.
            for i in (a_nb + 1)..=vemap.extent() {
                let Some(a_s) = vemap.value(i).cloned() else {
                    continue;
                };
                if a_s.shape_type() != ShapeType::Vertex {
                    continue;
                }

                // `cxx:540-551`: `aLF`, the faces reached through the vertex.
                let mut alf: Vec<TopoShape> = Vec::new();
                for edge in analyse.ancestors(&a_s) {
                    for face in analyse.ancestors(edge) {
                        if !alf.iter().any(|x| is_same(x, face)) {
                            alf.push(face.clone());
                        }
                    }
                }
                if alf.len() < 2 {
                    continue;
                }

                let mut alf1: Vec<TopoShape> = Vec::new();
                let mut alf2: Vec<TopoShape> = Vec::new();
                for idx in 0..alf.len() {
                    let a_fv1 = alf[idx].clone();

                    // `cxx:569-598`: the edges of `aFV1` that carry the
                    // vertex, unless `aFV1` has an internal edge.
                    let Some(le1) = analyse.descendants(&a_fv1, false) else {
                        continue;
                    };
                    let f1_internal = dmfei.get(&shape_map_key(&a_fv1));
                    let mut a_me: HashSet<ShapeMapKey> = HashSet::new();
                    let mut has_internal = false;
                    for a_e in &le1 {
                        if f1_internal.is_some_and(|m| m.contains(&shape_map_key(a_e))) {
                            has_internal = true;
                            break;
                        }
                        for v in explorer_shapes(a_e, ShapeType::Vertex) {
                            if is_same(&a_s, &v) {
                                a_me.insert(shape_map_key(a_e));
                                break;
                            }
                        }
                    }
                    if has_internal {
                        continue;
                    }

                    // `cxx:601-641`: the later faces that share no edge that
                    // is internal or has exactly two ancestors.
                    for other in alf.iter().skip(idx + 1) {
                        let a_fv2 = Face(other.clone());
                        let Some(le2) = analyse.descendants(&a_fv2.0, false) else {
                            continue;
                        };
                        let f2_internal = dmfei.get(&shape_map_key(&a_fv2.0));
                        let mut keep = true;
                        for a_ev2 in &le2 {
                            if !a_me.contains(&shape_map_key(a_ev2)) {
                                continue;
                            }
                            if f2_internal.is_some_and(|m| m.contains(&shape_map_key(a_ev2))) {
                                keep = false;
                                break;
                            }
                            if analyse.has_ancestor(a_ev2) && analyse.ancestors(a_ev2).len() == 2 {
                                keep = false;
                                break;
                            }
                        }
                        if keep {
                            alf1.push(a_fv1.clone());
                            alf2.push(a_fv2.0.clone());
                        }
                    }
                }

                if !alf1.is_empty() {
                    dmvlf1.insert(shape_map_key(&a_s), alf1);
                    dmvlf2.insert(shape_map_key(&a_s), alf2);
                }
            }
        }

        // `cxx:490-493`: the post-treatment indexes.
        let mut dm_int_e = IndexedListMap::new();
        let mut dm_int_ff: HashMap<ShapeMapKey, Vec<TopoShape>> = HashMap::new();

        // `cxx:654-850`: the main loop. `CurSide` starts from `mySide`
        // (`cxx:458`) but every surviving iteration assigns it again.
        a_nb = vemap.extent();
        for i in 1..=a_nb {
            let Some(a_s) = vemap.value(i).cloned() else {
                continue;
            };

            let cur_side: State;
            let mut e_ref: Option<Edge> = None;
            let mut alf1: Vec<TopoShape> = Vec::new();
            let mut alf2: Vec<TopoShape> = Vec::new();

            let b_edge = a_s.shape_type() == ShapeType::Edge;
            if b_edge {
                // `cxx:668-703`: the edge arm.
                let e = Edge(a_s.clone());
                let l = analyse.type_of(&e);
                let Some(first) = l.first() else {
                    continue;
                };
                let ot = first.kind();
                if ot != TypeOfConcavity::Convex && ot != TypeOfConcavity::Concave {
                    continue;
                }
                cur_side = if ot == TypeOfConcavity::Concave {
                    State::In
                } else {
                    State::Out
                };
                let anc = analyse.ancestors(&e.0);
                if anc.len() != 2 {
                    continue;
                }
                alf1.push(anc[0].clone());
                alf2.push(anc[anc.len() - 1].clone());
                e_ref = Some(e);
            } else {
                // `cxx:705-715`: the vertex arm.
                let Some(l1) = dmvlf1.get(&shape_map_key(&a_s)) else {
                    continue;
                };
                alf1 = l1.clone();
                alf2 = dmvlf2
                    .get(&shape_map_key(&a_s))
                    .cloned()
                    .unwrap_or_default();
                cur_side = self.side;
            }

            // `cxx:719-849`: the pair loop.
            for (f1_shape, f2_shape) in alf1.iter().zip(alf2.iter()) {
                let f1 = Face(f1_shape.clone());
                let f2 = Face(f2_shape.clone());

                let Some(of1) = map_sf
                    .get(&shape_map_key(&f1.0))
                    .and_then(|o| o.face())
                    .cloned()
                else {
                    continue;
                };
                let Some(of2) = map_sf
                    .get(&shape_map_key(&f2.0))
                    .and_then(|o| o.face())
                    .cloned()
                else {
                    continue;
                };

                // `cxx:729-753`: the enlarged offset faces, cached in `MES`.
                let Some(nf1) = Self::enlarged_offset_face(&f1, &of1, analyse, mes) else {
                    continue;
                };
                let Some(nf2) = Self::enlarged_offset_face(&f2, &of2, analyse, mes) else {
                    continue;
                };

                if !self.is_done(&nf1, &nf2) {
                    // `cxx:757-799`.
                    let mut l_int1: Vec<TopoShape> = Vec::new();
                    let mut l_int2: Vec<TopoShape> = Vec::new();
                    BRepOffsetTool::inter3d(
                        &nf1,
                        &nf2,
                        &mut l_int1,
                        &mut l_int2,
                        cur_side,
                        e_ref.as_ref(),
                        Some(&f1),
                        Some(&f2),
                    );
                    self.set_done(&nf1, &nf2);
                    if !l_int1.is_empty() {
                        self.store(&nf1, &nf2, &l_int1, &l_int2);

                        let mut shapes: Vec<TopoShape> = Vec::new();
                        if let Some(se) = build.get(&shape_map_key(&a_s)) {
                            shapes.extend(explorer_shapes(se, ShapeType::Edge));
                        }
                        for ne in &l_int1 {
                            shapes.push(ne.clone());
                            // `cxx:785-786`: the edge keeps its source shape.
                            dm_int_e.add_or_get(ne).push(a_s.clone());
                            // `cxx:788-791`: and the two faces that made it.
                            let ff = dm_int_ff.entry(shape_map_key(ne)).or_default();
                            ff.push(f1_shape.clone());
                            ff.push(f2_shape.clone());
                        }
                        build.insert(shape_map_key(&a_s), builder.make_compound_of(&shapes).0);
                    } else {
                        failed.push(a_s.clone());
                    }
                } else {
                    // `cxx:801-849`: `IsDone(NF1, NF2)`, the OCC4455 arm.
                    let l_int1 = self.as_des.descendant(&nf1.0).to_vec();
                    let l_int2 = self.as_des.descendant(&nf2.0).to_vec();
                    if !l_int1.is_empty() {
                        let mut shapes: Vec<TopoShape> = Vec::new();
                        if let Some(se) = build.get(&shape_map_key(&a_s)) {
                            shapes.extend(explorer_shapes(se, ShapeType::Edge));
                        }
                        for e1 in &l_int1 {
                            for e2 in &l_int2 {
                                if is_same(e1, e2) {
                                    shapes.push(e1.clone());
                                    if let Some(list) = dm_int_e.seek_mut(e1) {
                                        list.push(a_s.clone());
                                    }
                                }
                            }
                        }
                        build.insert(shape_map_key(&a_s), builder.make_compound_of(&shapes).0);
                    } else {
                        failed.push(a_s.clone());
                    }
                }
            }
        }

        // `cxx:852-1041`: one unique intersection edge per localized part.
        let n_int = dm_int_e.extent();
        for i in 0..n_int {
            let Some((a_e_shape, a_ls)) = dm_int_e.value(i).cloned() else {
                continue;
            };
            if a_ls.len() < 2 {
                continue;
            }
            let a_e = Edge(a_e_shape);
            let Some(lff) = dm_int_ff.get(&shape_map_key(&a_e.0)) else {
                continue;
            };
            let (Some(a_f1), Some(a_f2)) = (lff.first().cloned(), lff.last().cloned()) else {
                continue;
            };

            // `cxx:885-903`: the edges are the blocks' material, the vertices
            // are kept apart.
            let mut a_ms: HashSet<ShapeMapKey> = HashSet::new();
            let mut a_lv: Vec<TopoShape> = Vec::new();
            let mut ce_edges: Vec<TopoShape> = Vec::new();
            for s in &a_ls {
                a_ms.insert(shape_map_key(s));
                if s.shape_type() == ShapeType::Edge {
                    ce_edges.push(s.clone());
                } else {
                    a_lv.push(s.clone());
                }
            }

            // `cxx:906-948`: the edges of the two faces that connect two or
            // more localized parts.
            let mut me_connection: HashSet<ShapeMapKey> = HashSet::new();
            for a_f in [&a_f1, &a_f2] {
                for a_ef in explorer_shapes(a_f, ShapeType::Edge) {
                    let k = shape_map_key(&a_ef);
                    if a_ms.contains(&k) || me_connection.contains(&k) {
                        continue;
                    }
                    let v = edge_vertices(&Edge(a_ef.clone()));
                    let mut counter = 0;
                    for s in &a_ls {
                        for av in explorer_shapes(s, ShapeType::Vertex) {
                            let hit = v.0.as_ref().is_some_and(|x| is_same(&x.0, &av))
                                || v.1.as_ref().is_some_and(|x| is_same(&x.0, &av));
                            if hit {
                                counter += 1;
                                break;
                            }
                        }
                    }
                    if counter >= 2 {
                        ce_edges.push(a_ef.clone());
                        me_connection.insert(k);
                    }
                }
            }

            // `cxx:950-951`: the connexity blocks of those edges.
            let edges: Vec<Edge> = ce_edges.iter().map(|s| Edge(s.clone())).collect();
            let mut a_lcbe: Vec<Vec<TopoShape>> = make_connexity_blocks(edges)
                .into_iter()
                .map(|b| b.into_iter().map(|e| e.0).collect())
                .collect();

            // `cxx:953-983`: a vertex inside a block joins it, the others
            // become blocks of their own.
            let mut a_lcbv: Vec<Vec<TopoShape>> = Vec::new();
            for a_v in &a_lv {
                let mut found = false;
                for block in a_lcbe.iter_mut() {
                    let contains = block.iter().any(|member| {
                        explorer_shapes(member, ShapeType::Vertex)
                            .iter()
                            .any(|x| is_same(a_v, x))
                    });
                    if contains {
                        block.push(a_v.clone());
                        found = true;
                        break;
                    }
                }
                if !found {
                    a_lcbv.push(vec![a_v.clone()]);
                }
            }
            a_lcbe.extend(a_lcbv);
            if a_lcbe.len() == 1 {
                continue;
            }

            // `cxx:995-996`: the enlarged faces that receive the new edges.
            let Some(a_nf1) = map_sf
                .get(&shape_map_key(&a_f1))
                .and_then(|o| o.face())
                .and_then(|f| mes.get(&shape_map_key(&f.0)))
                .cloned()
            else {
                continue;
            };
            let Some(a_nf2) = map_sf
                .get(&shape_map_key(&a_f2))
                .and_then(|o| o.face())
                .and_then(|f| mes.get(&shape_map_key(&f.0)))
                .cloned()
            else {
                continue;
            };

            // `cxx:997-1039`: every block but the first gets a fresh instance.
            let (a_t1, a_t2) = BRepTool::edge_parameters(&a_e);
            let v = edge_vertices(&a_e);
            for block in a_lcbe.iter().skip(1) {
                let new_edge = AlgoTools::make_split_edge(
                    &a_e,
                    v.0.as_ref().map(|x| &x.0),
                    a_t1,
                    v.1.as_ref().map(|x| &x.0),
                    a_t2,
                );
                let Ok(new_edge) = new_edge else {
                    continue;
                };
                self.as_des.add(&a_nf1, &new_edge.0);
                self.as_des.add(&a_nf2, &new_edge.0);
                for a_s in block {
                    if me_connection.contains(&shape_map_key(a_s)) {
                        continue;
                    }
                    let Some(a_ci) = build.get(&shape_map_key(a_s)).cloned() else {
                        continue;
                    };
                    let mut shapes: Vec<TopoShape> =
                        explorer_shapes(&a_ci, ShapeType::Edge)
                            .into_iter()
                            .filter(|sx| !is_same(sx, &a_e.0))
                            .collect();
                    shapes.push(new_edge.0.clone());
                    build.insert(shape_map_key(a_s), builder.make_compound_of(&shapes).0);
                }
            }
        }
    }

    /// `MES` lookup / `CheckBounds` + `EnLargeFace` of one offset face
    /// (`cxx:729-753`): the enlarged face is cached under the offset face.
    fn enlarged_offset_face(
        f: &Face,
        of: &Face,
        analyse: &Analyse,
        mes: &mut ShapeMap,
    ) -> Option<Face> {
        if let Some(nf) = mes.get(&shape_map_key(&of.0)) {
            return Some(Face(nf.clone()));
        }
        let (enlarge_u, enlarge_vfirst, enlarge_vlast) = BRepOffsetTool::check_bounds(f, analyse);
        let opts = EnLargeFaceOptions {
            can_extent_surface: true,
            update_pcurve: true,
            enlarge_u,
            enlarge_vfirst,
            enlarge_vlast,
            ..EnLargeFaceOptions::default()
        };
        let (nf, _) = BRepOffsetTool::enlarge_face(of, &opts)?;
        mes.insert(shape_map_key(&of.0), nf.0.clone());
        Some(nf)
    }
}
